# Readings by interest, Spanish. Each: (id, level, title, emoji, topics, text, [(prompt, options, correct, explanation)])
R = [
 ('lectura_l1_luna_cielo', 1, 'La Luna', '🌙', ['espacio'],
  'Por la noche miro el cielo. Veo la Luna. A veces es redonda y grande. Otras veces parece una sonrisa. La Luna no tiene luz propia. Brilla porque le llega la luz del Sol.',
  [('¿Cuándo mira el cielo?', ['Por la mañana', 'Por la tarde', 'Por la noche'], 2, '«Por la noche miro el cielo.»'),
   ('¿Qué parece la Luna a veces?', ['Una estrella', 'Una sonrisa', 'Un cuadrado'], 1, '«Otras veces parece una sonrisa.»'),
   ('¿Por qué brilla la Luna?', ['Porque tiene luz propia', 'Porque le llega la luz del Sol', 'Porque es de fuego'], 1, '«Brilla porque le llega la luz del Sol.»')]),
 ('lectura_l2_baloncesto', 2, 'El partido de Sara', '🏀', ['deporte'],
  'Sara juega al baloncesto en el equipo del barrio. El sábado tienen un partido importante. Al principio, Sara falla tres tiros y se pone triste. Su entrenador le dice: «No pasa nada, sigue intentándolo». En el último minuto, Sara lanza el balón desde lejos. ¡Canasta! Su equipo gana por dos puntos y todos la abrazan.',
  [('¿A qué juega Sara?', ["Al fútbol sala", "Al baloncesto", "Al tenis de mesa"], 1, '«Sara juega al baloncesto.»'),
   ('¿Qué le dice el entrenador?', ['Que descanse', 'Que siga intentándolo', 'Que se vaya a casa'], 1, '«No pasa nada, sigue intentándolo.»'),
   ('¿Por cuántos puntos gana su equipo?', ['Por uno', 'Por dos', 'Por diez'], 1, '«Su equipo gana por dos puntos.»')]),
 ('lectura_l2_colores', 2, 'Mezclo colores', '🎨', ['arte', 'ciencia'],
  'Hoy en clase de plástica pintamos con témperas. La maestra nos trae tres colores: rojo, azul y amarillo. Si mezclo azul y amarillo, sale verde. Si mezclo rojo y amarillo, sale naranja. Y con rojo y azul, ¡sale morado! Con solo tres colores puedo pintar un arcoíris entero.',
  [('¿Con qué pintan?', ['Con lápices', 'Con témperas', 'Con ceras'], 1, '«Pintamos con témperas.»'),
   ('¿Qué color sale al mezclar azul y amarillo?', ['Verde', 'Naranja', 'Morado'], 0, '«Si mezclo azul y amarillo, sale verde.»'),
   ('¿Qué sale con rojo y azul?', ['Marrón', 'Verde', 'Morado'], 2, '«Y con rojo y azul, ¡sale morado!»')]),
 ('lectura_l3_planetas', 3, 'Nuestro vecindario: el sistema solar', '🪐', ['espacio', 'ciencia'],
  'La Tierra no está sola en el espacio. Forma parte del sistema solar, que tiene en el centro una estrella: el Sol. Alrededor del Sol giran ocho planetas. El más cercano es Mercurio, y el más lejano, Neptuno.\n\nCada planeta es muy diferente. Júpiter es el más grande de todos: dentro de él cabrían más de mil planetas como el nuestro. Marte se ve rojizo porque su suelo tiene mucho óxido de hierro. Y la Tierra es el único planeta donde sabemos que hay vida.',
  [('¿Qué hay en el centro del sistema solar?', ['La Tierra', 'El Sol', 'La Luna'], 1, '«Tiene en el centro una estrella: el Sol.»'),
   ('¿Cuál es el planeta más grande?', ['Marte', 'Neptuno', 'Júpiter'], 2, '«Júpiter es el más grande de todos.»'),
   ('¿Por qué Marte se ve rojizo?', ["Porque allí hace muchísimo calor siempre", "Porque su suelo tiene mucho óxido de hierro", "Porque está más cerca del Sol que la Tierra"], 1, '«Su suelo tiene mucho óxido de hierro.»')]),
 ('lectura_l3_orquesta', 3, 'Los instrumentos de la orquesta', '🎻', ['arte'],
  'En una orquesta tocan muchos músicos a la vez, y cada uno tiene su instrumento. Los instrumentos se agrupan en familias.\n\nLa familia de cuerda tiene violines, violas, violonchelos y contrabajos: suenan cuando se frotan sus cuerdas con un arco. La familia de viento incluye flautas, clarinetes y trompetas: suenan al soplar. La percusión, con tambores y platillos, suena al golpearla. Delante de todos está el director, que marca el ritmo con una batuta.',
  [('¿Cómo se agrupan los instrumentos?', ['Por colores', 'En familias', 'Por tamaños'], 1, '«Los instrumentos se agrupan en familias.»'),
   ('¿Cómo suenan los instrumentos de viento?', ['Al golpearlos', 'Al soplar', 'Al frotar sus cuerdas'], 1, '«Suenan al soplar.»'),
   ('¿Qué usa el director para marcar el ritmo?', ['Una batuta', 'Un tambor', 'Una flauta'], 0, '«Marca el ritmo con una batuta.»')]),
 ('lectura_l4_paralimpicos', 4, 'Los Juegos Paralímpicos', '🏅', ['deporte', 'historia'],
  'Cada cuatro años, después de los Juegos Olímpicos, se celebran los Juegos Paralímpicos. En ellos compiten deportistas con alguna discapacidad física, visual o intelectual.\n\nLos primeros se celebraron en Roma en 1960. Su origen está en un hospital de Inglaterra, donde un médico, Ludwig Guttmann, usaba el deporte para ayudar a recuperarse a soldados heridos en la guerra.\n\nHoy hay deportes como el baloncesto en silla de ruedas, la natación o el goalball, un juego para personas ciegas o con poca visión en el que la pelota lleva cascabeles. Los atletas paralímpicos demuestran que el talento y el esfuerzo no tienen límites.',
  [('¿Cuándo se celebran los Juegos Paralímpicos?', ['Antes de los Juegos Olímpicos', 'Después de los Juegos Olímpicos', 'Cada año'], 1, '«Después de los Juegos Olímpicos, se celebran los Juegos Paralímpicos.»'),
   ('¿Dónde se celebraron los primeros?', ['En Londres', 'En Roma', 'En Madrid'], 1, '«Los primeros se celebraron en Roma en 1960.»'),
   ('¿Qué tiene de especial la pelota del goalball?', ['Es muy grande', 'Lleva cascabeles', 'Es de madera'], 1, '«La pelota lleva cascabeles.»')]),
 ('lectura_l5_estacion', 5, 'Una casa en el espacio', '🛰️', ['espacio', 'tecnologia'],
  'A unos 400 kilómetros sobre nuestras cabezas, una enorme nave da vueltas alrededor de la Tierra: la Estación Espacial Internacional. Desde el año 2000 siempre hay astronautas viviendo en ella. La construyeron entre varios países, pieza a pieza, como si fuera un gigantesco juego de construcción.\n\nLa estación va tan rápida que da una vuelta completa a la Tierra en unos noventa minutos. Por eso, los astronautas ven unos dieciséis amaneceres al día. Allí todo flota: duermen en sacos atados a la pared, beben con pajitas de bolsas cerradas y hacen unas dos horas de ejercicio diario para que sus músculos y huesos no se debiliten.\n\nEn la estación se hacen experimentos que serían imposibles en la Tierra.',
  [('¿Desde cuándo hay siempre astronautas en la estación?', ['Desde 1969', 'Desde el año 2000', 'Desde el año pasado'], 1, '«Desde el año 2000 siempre hay astronautas viviendo en ella.»'),
   ('¿Cuánto tarda en dar una vuelta a la Tierra?', ["Un día entero", "Unos noventa minutos", "Una semana y media"], 1, '«Da una vuelta completa a la Tierra en unos noventa minutos.»'),
   ('¿Por qué hacen ejercicio los astronautas?', ["Para no aburrirse durante los viajes largos", "Para que sus músculos y huesos no se debiliten", "Para ganar una carrera contra otra nave"], 1, '«Para que sus músculos y huesos no se debiliten.»')]),
 ('lectura_l5_sorolla', 5, 'Sorolla, el pintor de la luz', '🖼️', ['arte', 'historia'],
  'Joaquín Sorolla nació en Valencia en 1863. Desde pequeño le encantaba dibujar, y con los años se convirtió en uno de los pintores españoles más famosos de su época.\n\nA Sorolla lo llaman «el pintor de la luz». Le gustaba pintar al aire libre, sobre todo en las playas de Valencia: niños bañándose, pescadores, barcas y velas blancas movidas por el viento. Pintaba deprisa, con pinceladas sueltas, para atrapar la luz del sol antes de que cambiara.\n\nHoy se pueden ver muchos de sus cuadros en el Museo Sorolla de Madrid, que fue su casa. Al mirarlos, parece que se oye el mar y se siente el calor del verano.',
  [('¿Dónde nació Sorolla?', ['En Madrid', 'En Valencia', 'En Sevilla'], 1, '«Joaquín Sorolla nació en Valencia en 1863.»'),
   ('¿Por qué pintaba deprisa?', ["Porque tenía prisa por ir a comer", "Para atrapar la luz antes de que cambiara", "Porque los cuadros pequeños se venden mejor"], 1, '«Para atrapar la luz del sol antes de que cambiara.»'),
   ('¿Qué fue antes el Museo Sorolla?', ['Un colegio', 'Su casa', 'Una playa'], 1, '«El Museo Sorolla de Madrid, que fue su casa.»')]),
 ('lectura_l6_dormir', 6, 'Dormir también es entrenar', '😴', ['deporte', 'ciencia', 'vida'],
  'Muchos deportistas de élite tienen algo en común que no se ve en las competiciones: se toman el sueño muy en serio. Saben que mientras dormimos el cuerpo repara los músculos, recupera la energía y fija lo aprendido durante el día, ya sea un movimiento nuevo o la lección de matemáticas.\n\nLos especialistas recomiendan que los adolescentes duerman entre ocho y diez horas cada noche. Sin embargo, muchos no llegan. Una de las causas son las pantallas: la luz del móvil por la noche engaña al cerebro, que retrasa la sensación de sueño, y los mensajes y los vídeos nos mantienen despiertos «solo cinco minutos más».\n\nDormir poco tiene consecuencias. Cuesta concentrarse, nos enfadamos con más facilidad, rendimos peor en el deporte y aumenta el riesgo de lesiones.\n\nAlgunos consejos sencillos ayudan: acostarse y levantarse a la misma hora, dejar el móvil fuera del dormitorio y no hacer ejercicio intenso justo antes de ir a la cama. Dormir bien no es perder el tiempo: es una parte más del entrenamiento.',
  [('Según el texto, ¿qué hace el cuerpo mientras dormimos?', ['Solo descansa la vista', 'Repara los músculos y fija lo aprendido', 'Quema toda la comida', 'El cerebro deja de funcionar'], 1, '«El cuerpo repara los músculos, recupera la energía y fija lo aprendido.»'),
   ('¿Cuántas horas se recomienda dormir a los adolescentes?', ['Entre cinco y seis', 'Entre seis y siete', 'Entre ocho y diez', 'Doce o más'], 2, '«Entre ocho y diez horas cada noche.»'),
   ('¿Por qué la luz del móvil dificulta dormirse?', ['Porque hace ruido', 'Porque engaña al cerebro y retrasa el sueño', 'Porque calienta la habitación', 'Porque gasta batería'], 1, '«Engaña al cerebro, que retrasa la sensación de sueño.»'),
   ('¿Cuál de estas NO es una consecuencia de dormir poco, según el texto?', ['Cuesta concentrarse', 'Aumenta el riesgo de lesiones', 'Se crece más deprisa', 'Rendimos peor en el deporte'], 2, 'El texto no dice nada sobre crecer más deprisa.'),
   ('¿Qué quiere decir la frase final?', ['Que dormir es aburrido', 'Que el descanso forma parte de la preparación', 'Que hay que entrenar de noche', 'Que los deportistas duermen poco'], 1, '«Es una parte más del entrenamiento.»')]),
 ('lectura_l7_marte', 7, '¿Hubo agua en Marte?', '🔴', ['espacio', 'ciencia'],
  'Visto desde la Tierra, Marte es un punto rojizo en el cielo. De cerca, es un desierto helado y polvoriento, con una atmósfera tan fina que no podríamos respirar en ella. Y, sin embargo, los científicos están convencidos de que hace miles de millones de años por su superficie corrían ríos y había lagos.\n\n¿Cómo lo saben? Las fotografías tomadas por satélites muestran cauces secos, deltas y rocas que solo se forman en presencia de agua. Además, en los polos de Marte hay casquetes de hielo, y bajo el suelo también se ha detectado hielo.\n\nEl agua líquida no puede permanecer mucho tiempo en la superficie actual: la presión es tan baja que se evaporaría o se congelaría enseguida. Por eso, los robots exploradores buscan pistas del pasado. El rover Perseverance aterrizó en 2021 en el cráter Jezero, donde hubo un lago, para recoger muestras de roca que, en el futuro, podrían traerse a la Tierra.\n\nLa gran pregunta sigue abierta: si Marte tuvo agua, ¿llegó a tener vida? Encontrar la respuesta podría cambiar lo que sabemos sobre nuestro lugar en el universo.',
  [('¿Cómo es hoy la superficie de Marte?', ['Un océano cálido', 'Un desierto helado y polvoriento', 'Una selva húmeda', 'Una llanura cubierta de hierba'], 1, '«Es un desierto helado y polvoriento.»'),
   ('¿Qué pruebas indican que hubo agua?', ['Que Marte se ve rojo', 'Cauces secos, deltas y rocas que se forman con agua', 'Que tiene una atmósfera fina', 'Que está lejos del Sol'], 1, '«Cauces secos, deltas y rocas que solo se forman en presencia de agua.»'),
   ('¿Por qué no puede haber agua líquida mucho tiempo en la superficie?', ['Porque hay demasiados robots', 'Porque la presión es muy baja', 'Porque hay demasiado oxígeno', 'Porque nunca hay viento'], 1, '«La presión es tan baja que se evaporaría o se congelaría enseguida.»'),
   ('¿Para qué fue Perseverance al cráter Jezero?', ['Para buscar oro', 'Para construir una base', 'Para recoger muestras de roca donde hubo un lago', 'Para hacer fotos de la Tierra'], 2, '«Para recoger muestras de roca.»'),
   ('¿Cuál es «la gran pregunta» del final?', ['Si Marte es rojo', 'Si Marte llegó a tener vida', 'Cuándo llegará el próximo robot', 'Si hay hielo en los polos'], 1, '«Si Marte tuvo agua, ¿llegó a tener vida?»')]),
 ('lectura_l8_ia', 8, '¿Piensan las máquinas?', '🤖', ['tecnologia'],
  'Hoy hablamos con asistentes de voz, recibimos recomendaciones de vídeos y traducimos textos en segundos gracias a la inteligencia artificial (IA). Algunos programas escriben redacciones o crean imágenes a partir de una frase. Ante resultados tan sorprendentes, es fácil preguntarse si estas máquinas piensan como nosotros.\n\nLa respuesta de la mayoría de los expertos es más prudente. Estos sistemas aprenden analizando enormes cantidades de datos y detectan patrones: qué palabra suele ir después de otra o qué forma tiene un gato en miles de fotos. Gracias a eso pueden dar respuestas muy convincentes, pero no tienen experiencias ni una comprensión del mundo como la humana. Y a veces se equivocan con total seguridad.\n\nPor eso conviene usarlos con espíritu crítico. Una IA puede ayudarnos a organizar ideas o a repasar, pero si le dejamos hacer todo el trabajo, no aprendemos. Además, hay que comprobar la información que nos da, igual que haríamos con cualquier página de internet.\n\nLa inteligencia artificial es una herramienta poderosa. Que nos haga mejores o más perezosos dependerá, en gran parte, de cómo decidamos utilizarla.',
  [('Según el texto, ¿cómo aprenden estos sistemas?', ['Leyendo la mente de las personas', 'Analizando muchos datos y detectando patrones', 'Asistiendo a clase', 'Copiando a otras máquinas'], 1, '«Aprenden analizando enormes cantidades de datos y detectan patrones.»'),
   ('¿Qué opina la mayoría de los expertos?', ['Que piensan igual que nosotros', 'Que no comprenden el mundo como los humanos', 'Que nunca se equivocan', 'Que pronto irán al colegio'], 1, '«No tienen experiencias ni una comprensión del mundo como la humana.»'),
   ('¿Qué problema se menciona?', ['Que son muy lentas', 'Que a veces se equivocan con total seguridad', 'Que solo funcionan en inglés', 'Que no se pueden usar en casa'], 1, '«A veces se equivocan con total seguridad.»'),
   ('¿Qué recomienda el texto?', ['No usarlas nunca', 'Usarlas con espíritu crítico y comprobar la información', 'Dejar que hagan los deberes', 'Creer todo lo que dicen'], 1, '«Conviene usarlos con espíritu crítico.»'),
   ('¿Qué tipo de texto es?', ['Un cuento de fantasía', 'Un texto argumentativo que invita a reflexionar', 'Una receta', 'Un poema'], 1, 'Expone una pregunta, da argumentos y termina con una reflexión.')]),
 ('lectura_l9_guernica', 9, 'Guernica: un grito pintado', '🖤', ['arte', 'historia'],
  'El 26 de abril de 1937, en plena guerra civil española, aviones alemanes e italianos, aliados de las tropas de Franco, bombardearon la villa vasca de Gernika. Era día de mercado. La villa quedó en gran parte destruida y murieron numerosos civiles; todavía hoy los historiadores debaten la cifra exacta.\n\nPablo Picasso vivía entonces en París y había recibido el encargo de pintar un mural para el pabellón de la República española en la Exposición Internacional de ese año. Conmocionado por las noticias, decidió que su obra hablaría del horror de aquel bombardeo. En poco más de un mes pintó un lienzo de casi ocho metros de ancho.\n\nEl Guernica no muestra aviones ni explosiones. En su lugar aparecen figuras deformadas: una madre que grita con su hijo muerto en brazos, un caballo herido, un toro, una bombilla que parece un ojo. Picasso eligió solo el blanco, el negro y los grises, como en las fotografías de los periódicos.\n\nPor deseo del pintor, el cuadro no viajó a España hasta que se recuperó la democracia: llegó en 1981. Hoy se encuentra en el Museo Reina Sofía, en Madrid, y se ha convertido en un símbolo universal contra la guerra.',
  [('¿Qué ocurrió el 26 de abril de 1937?', ['Se inauguró un museo', 'Bombardearon la villa de Gernika', 'Picasso llegó a París', 'Terminó la guerra'], 1, '«Bombardearon la villa vasca de Gernika.»'),
   ('¿Para qué lugar pintó Picasso el cuadro?', ['Para su casa de París', 'Para el pabellón de la República en la Exposición Internacional', 'Para el ayuntamiento de Gernika', 'Para el Museo del Prado'], 1, '«Un mural para el pabellón de la República española en la Exposición Internacional.»'),
   ('¿Con qué relaciona el texto los colores del cuadro?', ['Con las fotografías de los periódicos', 'Con la bandera de España', 'Con el mar de noche', 'Con los colores del mercado'], 0, '«Como en las fotografías de los periódicos.»'),
   ('¿Cuándo llegó el Guernica a España?', ['En 1937', 'En 1981', 'En 1992', 'En 2000'], 1, '«Llegó en 1981.»'),
   ('¿Por qué se ha convertido en un símbolo?', ['Porque es el cuadro más caro', 'Porque expresa el horror de la guerra de forma universal', 'Porque tiene muchos colores', 'Porque es muy pequeño'], 1, '«Se ha convertido en un símbolo universal contra la guerra.»')]),
]
